// The content-block and job-identity shape is declaration-driven: the
// annotation below is the real command's generated annotation with every
// binding renamed at generation time (a fixed prefix on each declared or
// defaulted member name, so the synthetic shape is guaranteed distinct from
// the real one whatever the document declares). Injecting it over the
// generated command and serving a body in that shape proves the runtime
// reads the declared members — a runtime that assumed the default names
// would find no content.
const artifactCustomShapeAnnotation = "{\"pointer\":[{\"field\":\"steps\"},{\"wild\":true},{\"field\":\"content\"},{\"wild\":true}],\"kind\":\"image\",\"defaultPath\":\"render-{timestamp}-{rand}.{ext}\",\"typeField\":\"custom_type\",\"dataField\":\"custom_data\",\"mimeTypeField\":\"custom_mime_type\",\"uriField\":\"custom_uri\",\"idField\":\"custom_id\",\"statusField\":\"custom_status\",\"terminalStatus\":\"custom_completed\"}"

// runArtifactCustomShape mirrors runArtifact but rebinds the artifact
// command's speakeasy_artifact annotation to artifactCustomShapeAnnotation
// on a fresh command tree before executing.
func runArtifactCustomShape(t *testing.T, h *CLITestHarness, serverURL, dir string, extra ...string) error {
	t.Helper()
	orig, err := os.Getwd()
	require.NoError(t, err)
	require.NoError(t, os.Chdir(dir))
	t.Cleanup(func() { _ = os.Chdir(orig) })
	h.resetAndSetupEnv()
	rootCmd, err := cli.NewRootCommand()
	require.NoError(t, err)
	rootCmd.SetOut(h.stdout)
	rootCmd.SetErr(h.stderr)
	rootCmd.SetIn(strings.NewReader(""))

	target := rootCmd
	for _, segment := range []string{"render"} {
		found := false
		for _, child := range target.Commands() {
			if child.Name() == segment {
				target = child
				found = true
				break
			}
		}
		require.True(t, found, "artifact command segment %q not found", segment)
	}
	require.Contains(t, target.Annotations, "speakeasy_artifact")
	annotations := map[string]string{}
	for key, value := range target.Annotations {
		annotations[key] = value
	}
	annotations["speakeasy_artifact"] = artifactCustomShapeAnnotation
	target.Annotations = annotations

	args := append([]string{"render", "a test prompt"}, extra...)
	fullArgs := append(append(baseArgs(), "--server-url", serverURL, "--color", "never"), args...)
	return cli.ExecuteRoot(context.Background(), rootCmd, fullArgs)
}

func TestArtifact_DeclaredShapeDrivesExtraction(t *testing.T) {
	server := artifactTestServer(t, `{"custom_id":"task-123","custom_status":"custom_completed","steps":[{"content":[{"custom_type":"image","custom_data":"YXJ0aWZhY3QtYnl0ZXM=","custom_mime_type":"image/png"}]}]}`)
	dir := t.TempDir()
	h := NewCLITestHarness(t)

	require.NoError(t, runArtifactCustomShape(t, h, server.URL, dir, "--output-format", "json"))
	stdout := h.GetStdout()
	written := jsonGetString(stdout, "path")
	require.NotEmpty(t, written, "envelope must carry the artifact path")
	payload, err := os.ReadFile(written)
	require.NoError(t, err)
	assert.Equal(t, artifactTestBytes, string(payload))
	assert.Equal(t, "image/png", jsonGetString(stdout, "mime_type"))
	assert.Equal(t, "task-123", jsonGetString(stdout, "response_id"), "identity idField binding must feed response_id")
	assert.Equal(t, "custom_completed", jsonGetString(stdout, "status"), "identity statusField binding must feed status")

	// The same custom-shaped body must NOT satisfy the default-shape command:
	// the declaration, not a hardcoded probe, decides the member names.
	h2 := NewCLITestHarness(t)
	err = runArtifact(t, h2, server.URL, dir)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "no image content")
}

func TestArtifact_DeclaredShapeNotReadyDiagnostics(t *testing.T) {
	server := artifactTestServer(t, `{"custom_id":"task-123","custom_status":"artifact_test_pending","steps":[{"content":[]}]}`)
	dir := t.TempDir()
	h := NewCLITestHarness(t)

	err := runArtifactCustomShape(t, h, server.URL, dir)
	require.Error(t, err)
	assert.Contains(t, err.Error(), "no image content")
	assert.Contains(t, err.Error(), `status "artifact_test_pending"`, "the declared statusField and terminalStatus drive the not-ready diagnostic")
	assert.Contains(t, err.Error(), `id "task-123"`, "the declared idField feeds the not-ready diagnostic")
	assert.Contains(t, err.Error(), "may not be ready yet")
}

type artifactPrompter struct {
	answers map[string][]string
	fields  []interactive.PromptField
	calls   int
}

func (p *artifactPrompter) Prompt(_ *cobra.Command, fields []interactive.PromptField) ([]interactive.PromptAnswer, error) {
	p.calls++
	p.fields = append([]interactive.PromptField(nil), fields...)
	answers := make([]interactive.PromptAnswer, len(fields))
	for i, field := range fields {
		if values, ok := p.answers[field.ID]; ok {
			answers[i] = interactive.PromptAnswer{Set: true, Values: values}
		}
	}
	return answers, nil
}

func runArtifactInteractive(t *testing.T, h *CLITestHarness, serverURL, dir string, p interactive.Prompter, extra ...string) error {
	t.Helper()
	orig, err := os.Getwd()
	require.NoError(t, err)
	require.NoError(t, os.Chdir(dir))
	t.Cleanup(func() { _ = os.Chdir(orig) })
	h.resetAndSetupEnv()
	rootCmd, err := cli.NewRootCommand()
	require.NoError(t, err)
	rootCmd.SetOut(h.stdout)
	rootCmd.SetErr(h.stderr)
	// Prompting is opt-in at runtime (--interactive; interactiveByDefault may be false).
	args := []string{"--interactive", "--server-url", serverURL, "--color", "never", "render"}
	args = append(args, extra...)
	ctx := interactive.WithPrompter(context.Background(), p)
	return cli.ExecuteRoot(ctx, rootCmd, args)
}

func TestArtifact_InteractiveOutputFileIsDirect(t *testing.T) {
	server := artifactTestServer(t, `{"id":"task-123","status":"completed","steps":[{"content":[{"type":"image","data":"YXJ0aWZhY3QtYnl0ZXM=","mime_type":"image/png"}]}]}`)
	dir := t.TempDir()
	target := filepath.Join(dir, "chosen.png")
	p := &artifactPrompter{answers: map[string][]string{
		"arg:" + "prompt": {"interactive artifact"},
		"flag:out":        {target},
	}}
	h := NewCLITestHarness(t)
	require.NoError(t, runArtifactInteractive(t, h, server.URL, dir, p))
	assert.Equal(t, target, strings.TrimSpace(h.GetStdout()))
	require.GreaterOrEqual(t, len(p.fields), 2)
	assert.Equal(t, "arg:"+"prompt", p.fields[0].ID)
	assert.Equal(t, "flag:out", p.fields[1].ID)
	assert.True(t, p.fields[1].Direct)
	assert.Equal(t, "Output file", p.fields[1].Name)
	assert.Contains(t, p.fields[1].Summary, "into this directory")
	assert.Contains(t, p.fields[1].Summary, "render-{timestamp}-{rand}.{ext}")
	assert.Contains(t, p.fields[1].Summary, "optional; leave empty for the default")
}

